mapper.sql:
WHERE c.state <> 'deleted'
AND p.board_id = #{boardId}
AND (c.content LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\' OR u.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\')

mapper.select:
SELECT c.comment_id AS commentId, c.post_id AS postId, p.board_id AS boardId, b.name AS boardName, u.name AS authorName,
CASE WHEN u.is_deleted = 1 THEN NULL ELSE u.login_id END AS authorLoginId, CASE WHEN u.is_deleted = 1 THEN NULL ELSE u.student_no END AS authorStudentNo, c.content, c.created_at AS created, c.state FROM comments c INNER JOIN posts p ON c.post_id = p.post_id INNER JOIN boards b ON p.board_id = b.board_id INNER JOIN users u ON c.user_id = u.user_id
ORDER BY c.created_at DESC LIMIT #{size} OFFSET #{offset}
